{"mcp":"{
	"servers": {
		"io.github.patrickchugh/terravision": {
			"type": "stdio",
			"command": "uvx",
			"args": [
				"--from",
				"terravision[mcp]",
				"--index-url",
				"https://pypi.org",
				"terravision@0.46.4",
				"mcp"
			],
			"gallery": "https://api.mcp.github.com",
			"version": "0.46.4"
		},
		"io.cpln/control-plane": {
			"type": "http",
			"url": "https://mcp.cpln.io/mcp",
			"gallery": "https://api.mcp.github.com",
			"version": "1.0.2"
		},
		"coplaydev/unity-mcp": {
			"type": "stdio",
			"command": "other",
			"args": [
				"--directory",
				"${input:unity_mcp_server_src}",
				"run",
				"server.py"
			],
			"gallery": "https://api.mcp.github.com",
			"version": "1.0.0"
		},
		"io.github.upstash/context7": {
			"type": "http",
			"url": "https://mcp.context7.com/mcp",
			"headers": {
				"Authorization": "${input:Authorization}"
			},
			"gallery": "https://api.mcp.github.com",
			"version": "4.0.5"
		},
		"io.github.wonderwhy-er/desktop-commander": {
			"type": "stdio",
			"command": "npx",
			"args": [
				"--registry",
				"https://registry.npmjs.org",
				"@wonderwhy-er/desktop-commander@0.2.48"
			],
			"gallery": "https://api.mcp.github.com",
			"version": "0.2.48"
		},
		"com.stripe/mcp": {
			"type": "http",
			"url": "https://mcp.stripe.com",
			"gallery": "https://api.mcp.github.com",
			"version": "0.2.4"
		}
	},
	"inputs": [
		{
			"id": "unity_mcp_server_src",
			"type": "promptString",
			"description": "Absolute path to the Unity MCP Server 'src' folder installed by the Unity package (e.g., macOS: ~/Library/Application Support/UnityMCP/UnityMcpServer/src; Windows: %USERPROFILE%/AppData/Local/UnityMCP/UnityMcpServer/src; Linux: ~/.local/share/UnityMCP/UnityMcpServer/src).",
			"password": false
		},
		{
			"id": "Authorization",
			"type": "promptString",
			"description": "API key for authentication. Accepts \"Bearer <key>\" or the raw key.",
			"password": true
		}
	]
}"}
